content = '''import sys
try:
    from PIL import Image
except ImportError:
    import subprocess
    subprocess.check_call([sys.executable, "-m", "pip", "install", "Pillow"])
    from PIL import Image

img = Image.open(r"C:\\Repos\\Firecraft-CraftAnything-Experiment\\reference\\picture-1.jpg")
width, height = img.size

# Canvas area - look for the document area
canvas_center = []
for y in range(int(height * 0.2), int(height * 0.8)):
    for x in range(int(width * 0.15), int(width * 0.75), 10):
        canvas_center.append(img.getpixel((x, y)))

def avg_color(pixels):
    if not pixels:
        return (0, 0, 0)
    r = sum(p[0] for p in pixels) // len(pixels)
    g = sum(p[1] for p in pixels) // len(pixels)
    b = sum(p[2] for p in pixels) // len(pixels)
    return (r, g, b)

print(f"Canvas center: {avg_color(canvas_center)}")

# Also check the document area specifically (lighter rectangle in the center)
doc_area = []
for y in range(int(height * 0.25), int(height * 0.75)):
    for x in range(int(width * 0.2), int(width * 0.6), 10):
        doc_area.append(img.getpixel((x, y)))

print(f"Document area: {avg_color(doc_area)}")
'''

with open(path, 'w') as f:
    f.write(content)
print("Canvas center analysis written")

